mapper.select:
select * from KCC_EGIS.egis.TBL_MEMBER where 1=1
and id = #{id}
and chk_state = 'S'

mapper.insert:
insert into KCC_EGIS.egis.TBL_MEMBER (
	 id, sha_pwd, name, jumin, zipcode, addr, daddr, email, tel
	,chk_email, chk_sms ,chk_grade , chk_state ,reg_date ,login_date,logindate,out_date
	,pwd_date,ip,sex,di
)values(
	 #{id}, #{pwd}, #{name}, #{jumin}, #{zipcode}, #{addr}, #{daddr}, #{email}, #{tel}
	,#{chk_email}, 'N' , '10', 'S', getdate(), CONVERT(VARCHAR(10), GETDATE(), 120),getdate(),'1900-01-01 00:00:00'
	,CONVERT(VARCHAR(10), GETDATE(), 120),#{ip},#{sex},#{di}
)

mapper.select:
select count(*) from KCC_EGIS.egis.TBL_MEMBER 
where 1=1 


		and id = #{id}




		and email = #{email}




		and num != #{num}
